theorem.content:
\label{lem:minimaxless}
Let $X\subseteq \mathbb{R}^d$, $Y\subseteq \mathbb{R}^k$, and $f:X\times Y \to \mathbb{R}$.
Then 
\begin{equation}\label{eq:minimaxless}
\sup_{\mathbf{x}\in X} \inf_{\mathbf{y}\in Y} f(\mathbf{x},\mathbf{y}) \leq \inf_{\mathbf{y}\in Y} \sup_{\mathbf{x}\in X} f(\mathbf{x},\mathbf{y}).
\end{equation}

ref_dict.lem:minimaxless:
\begin{lemma}\label{lem:minimaxless}
Let $X\subset \R^d$, $Y\subset \R^k$, and $f:X\times Y \to \R$.
Then 
\begin{equation}\label{eq:minimaxless}
\sup_{\x\in X} \inf_{\y\in Y} f(\x,\y) \leq \inf_{\y\in Y} \sup_{\x\in X} f(\x,\y).
\end{equation}
\end{lemma}

